// requested by them weren't confirmed by the upstream event source and they didn't enable
// partial success mode.
func (f *Fanout) SetInit(confirmedKinds []types.WatchKind) {
	f.mu.Lock()
	defer f.mu.Unlock()
	if f.init {
		return
